### Recommended request flow

1. Validate the text and language codes.
2. Build a cache key from **source language, target language, and text**—not text alone, or different language pairs could collide.
3. Check Redis first.
4. On a cache miss, call DeepL asynchronously with a timeout.
5. Cache successful translations. If Redis is unavailable, continue to DeepL rather than failing the request.
6. Retry only transient failures, especially `429` and selected `5xx` responses; use a small retry limit and exponential backoff with jitter so retries don’t inflate normal response times.

Example for an Express service using Axios and the Redis v4 client:

```js
const express = require('express');
const axios = require('axios');
const { createHash } = require('node:crypto');

const app = express();
app.use(express.json());

const redis = require('redis');
const cache = redis.createClient({ url: process.env.REDIS_URL });

cache.on('error', (err) => console.error('Redis error:', err));
cache.connect().catch((err) => console.error('Redis connect failed:', err));

const deepl = axios.create({
  baseURL: 'https://api.deepl.com/v2',
  timeout: 2500, // Set to suit your latency budget
  headers: {
    Authorization: `DeepL-Auth-Key ${process.env.DEEPL_API_KEY}`,
  },
});

function cacheKey({ text, sourceLang, targetLang }) {
  const digest = createHash('sha256')
    .update(`${sourceLang ?? 'auto'}\0${targetLang}\0${text}`)
    .digest('hex');

  return `translation:${digest}`;
}

app.post('/api/translate', async (req, res, next) => {
  const { text, sourceLang, targetLang } = req.body ?? {};

  if (typeof text !== 'string' || !text.trim() ||
      typeof targetLang !== 'string') {
    return res.status(400).json({ error: 'text and targetLang are required' });
  }

  const key = cacheKey({ text, sourceLang, targetLang });

  try {
    // Cache failures should not prevent translation.
    try {
      const cached = await cache.get(key);
      if (cached !== null) {
        return res.json({ translatedText: cached, cached: true });
      }
    } catch (err) {
      console.warn('Redis read failed:', err.message);
    }

    const payload = {
      text: [text],
      target_lang: targetLang.toUpperCase(),
      ...(sourceLang && { source_lang: sourceLang.toUpperCase() }),
    };

    const { data } = await deepl.post('/translate', payload);
    const translatedText = data.translations?.[0]?.text;

    if (typeof translatedText !== 'string') {
      throw new Error('DeepL returned no translation');
    }

    try {
      await cache.set(key, translatedText, { EX: 1200 }); // 20-minute TTL
    } catch (err) {
      console.warn('Redis write failed:', err.message);
    }

    return res.json({ translatedText, cached: false });
  } catch (err) {
    next(err);
  }
});
```

